class Solution:
    def twoSum(self, nums: list[int], target: int) -> list[int]:
        # First pass: Store all numbers and their indices in a hash map
        num_to_index = {}
        for i, num in enumerate(nums):
            num_to_index[num] = i

        # Second pass: For each number, check if its complement exists in the hash map
        for i, num in enumerate(nums):
            complement = target - num
            # Check if complement exists and is not the current number itself
            if complement in num_to_index and num_to_index[complement] != i:
                return [i, num_to_index[complement]]

